*/
scwin.findIsuDigital = async function (dgtype) {
    /* sdd-asis-lifecycle:begin fn_findIsuDigital — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (dgtype === '3') {
        if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '') {
            await $c.win.alert('대상회사를 선택하십시요');
            return;
        }
    }
    const txtIsurCd = $c.util.getComponent('ipt_txtisurCd').getValue();
    const txtFormCd = $c.util.getComponent('dma_documentWriteReq').get('formCd');
    const isuSearchURL = '/jldfil00033/jldfil00033.xml';
    scwin.setCorpInfo_recv(await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(isuSearchURL), { id: "isuWin", scrollbars: false, resizable: false, width: "600", height: "660", type: "pageFramePopup" }, { method: "loadInitPageIsu", isurCd: txtIsurCd, formCd: txtFormCd }));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
