    $c.util.getComponent("ipt_txtisurCd").setValue(isurCd);
    $c.util.getComponent("ipt_txtfssUnqNo").setValue(fssUnqNo);
    $c.util.getComponent("ipt_txtisuNm").setValue(isuKorAbbrv);
    $c.util.getComponent("ipt_txtisuCd_2").setValue(repIsuCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuSrtCd', repIsuSrtCd);
