    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "2");
    scwin.moveStep = true;
    if (($c.util.getComponent('ipt_txtisurCd').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisurCd').getValue())) === '' || ($c.util.getComponent('ipt_txtfssUnqNo').getValue() == null ? '' : String($c.util.getComponent('ipt_txtfssUnqNo').getValue())) === '' || ($c.util.getComponent('ipt_txtcomNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtcomNm').getValue())) === '') {
        await $c.win.alert('대상회사를 선택하십시요');
        return;
    }
    if (($c.util.getComponent('ipt_txtisuCd_2').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisuCd_2').getValue())) === '' || ($c.util.getComponent('ipt_txtisuNm').getValue() == null ? '' : String($c.util.getComponent('ipt_txtisuNm').getValue())) === '') {
        await $c.win.alert('대상종목를 선택하십시요');
        return;
    }
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsurCd', $c.util.getComponent('ipt_txtisurCd').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtFssUnqNo', $c.util.getComponent('ipt_txtfssUnqNo').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtComNm', $c.util.getComponent('ipt_txtcomNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuNm', $c.util.getComponent('ipt_txtisuNm').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('tgtIsuCd', $c.util.getComponent('ipt_txtisuCd_2').getValue());
    $c.util.getComponent('dma_documentWriteReq').set('corpisuBasTpCd', "2");
    scwin.moveStep = true;
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
    /* sdd-asis-lifecycle:end */
};



